# exam helper: name, typical window, conducting body
def ex(name, window, body):
    return {"name": name, "typical_window": window, "body": body,
            "note": "Check the official notification every cycle; dates move."}

def tiers(t1, t2, t3):
    return {"tier1": t1, "tier2": t2, "tier3": t3}

def pay(entry, mid, senior):
    return {"currency": "INR", "unit": "lakh per annum", "entry": entry, "mid": mid, "senior": senior,
            "note": "Indicative metro ranges; varies widely by city and employer."}

